  Atendimentos:[
    'pessoaId','demanda','referencia','parcelas','outrosCasos','observacoes',
    'responsavel','situacao','folderId','revisao','conferencia','enderecamento',
    'secaoJudiciaria','valorCausa','localData'
  ],
  Documentos:[
    'atendimentoId','categoria','fileId','url','nome','hash','mime','substituiId',
    'vigente','vencimento','terceiro','conferido','declaracaoTerceiro',
    'processoCompleto','anexoPresente','rogo','testemunhas','observacoes'
  ],
  Pendencias:['atendimentoId','descricao','responsavel','situacao'],
  Minutas:[
    'atendimentoId','fileId','url','numero','situacao','snapshot','templateId',
    'templateModified','revisor','revisadaEm','pdfFileId','pdfUrl'
  ],
  Historico:['entidade','registroId','antes','depois','operacao'],
  Configuracoes:['chave','valor'],
  Usuarios:['email','perfil','ativo','nome','funcao','permissoes','permissoesVersao',
    'senhaHash','senhaSalt','senhaAlgoritmo','sessionVersion','ultimoLogin',
    'nomeUsuario','fotoId','emailsAnteriores'],
  Sessoes:['usuarioId','tokenHash','expiraEm','sessionVersion','revogada'],
  Recuperacoes:['usuarioId','tokenHash','expiraEm','sessionVersion','usada'],
  Distribuicao:['atendimentoId','processoId','numero','juizo','data','responsavel','protocoloId'],
  Tarefas:[
    'tipo','pessoaId','responsavel','situacao','jurisdicao','valorCausa',
    'atribuidaEm','concluidaEm','processoId','observacoes'
  ],
  Processos:['pessoaId','atendimentoId','numero','juizo','distribuidoEm','responsavel','movimentacoes'],
  Operacoes:['hash','resultado']
});

const COMMON=['id','versao','criadoEm','alteradoEm','usuario'];

const JURISDICOES = Object.freeze({
 'PELOTAS':['Amaral Ferrador','Arroio do Padre','Arroio Grande','Canguçu','Capão do Leão','Cerrito','Herval','Jaguarão','Morro Redondo','Pedro Osório','Pelotas','Piratini','São Lourenço do Sul','Turuçu'],
 'RIO GRANDE':['Chuí','Rio Grande','Santa Vitória do Palmar','São José do Norte'],
 'CAPÃO DA CANOA':['Arroio do Sal','Balneário Pinhal','Capão da Canoa','Caraá','Cidreira','Dom Pedro de Alcântara','Imbé','Itati','Mampituba','Maquiné','Morrinhos do Sul','Osório','Terra de Areia','Torres','Tramandaí','Três Cachoeiras','Três Forquilhas','Xangri-lá']
});
const LEGACY_ENTIDADES_PADRAO=Object.freeze([
  'COPAPEL — COLÔNIA DOS PESCADORES E AQUICULTORES PROFISSIONAIS ARTESANAIS DE PELOTAS',
  'COLÔNIA Z-1',
  'COLÔNIA Z-2',
  'COLÔNIA Z-3',
  'COLÔNIA Z-11',
  'Outro'
]);

const ENTIDADES_PADRAO=Object.freeze([
  'COPAPEL',
  'RIG - COLÔNIA Z-1',
  'SJN - COLÔNIA Z-2',
  'PEL - COLÔNIA Z-3',
  'SLS - COLÔNIA Z-8',
  'TAV - COLÔNIA Z-11',
  'AGR - COLÔNIA Z-24',
  'Outro'
]);

const DEFAULTS={
  rascunhos:'PENDENTE',
  vencimentoFuturo:'PENDENTE',
  anexoOrientacao:'',
  templateId:'',
  templateAprovado:false,
  entidades:Array.from(ENTIDADES_PADRAO),
  municipios:Object.values(JURISDICOES).flat().sort((a,b)=>a.localeCompare(b,'pt-BR')),
  demandas:['Seguro-Defeso 2025'],
  categorias:['RG_CPF','RESIDENCIA','PROCESSO_ADMINISTRATIVO','PESCA','PROCURACAO','HIPOSSUFICIENCIA'],
  situacoes:['EM_PREPARACAO','ENCAMINHADO','CONFERIDO'],
  advogadosDistribuicao:[
    'JOSÉ RICARDO CAETANO COSTA — OAB/RS 028.912',
    'THELMO DE CARVALHO TEIXEIRA BRANCO FILHO — OAB/RS 132.839B',
    'GUILHERME HOMMERDING ALT — OAB/RS 053.288',
    'PATRÍCIA DE ALMEIDA OLIVEIRA — OAB/RS 127.669',
    'LUIZE LIMA DA ROSA — OAB/RS 104.145',
    'YAGO FREITAS BLANCO — OAB/RS 137.930',
    'JOÃO PEDRO DE OLIVEIRA SIMÕES LOPES GASTAL — OAB/RS 129.245'
  ]
};

const ROLES={
  CONSULTA:['consulta'],
  NOVO_USUARIO:['consulta','cadastro'],
  PROFESSOR_RESIDENTE:[
    'consulta','cadastro','retificacao','conferencia','minuta','gestao_distribuicao'
  ],
  COLABORADOR:[
    'consulta','cadastro','retificacao_propria'
  ],
  ALUNO:[
    'consulta','distribuicao'
  ],
  CADASTRO:['consulta','cadastro'],
  CONFERENCIA:['consulta','cadastro','retificacao','conferencia'],
  JURIDICO:[
    'consulta','cadastro','retificacao','conferencia','minuta','distribuicao'
  ],
  ADMIN:[
    'consulta','cadastro','retificacao','conferencia','minuta',
    'distribuicao','gestao_distribuicao','administracao'
  ]
};

const PERMISSIONS=Object.freeze({
  consulta:{
    label:'Consulta',
    descricao:'Visualizar painel, pessoas, fichas, documentos e processos sem alterar registros.'
  },
  cadastro:{
    label:'Cadastro',
    descricao:'Criar novas pessoas, anexar documentos durante a inclusão e concluir novos cadastros. Não é necessária para editar registros já existentes.'
  },
  retificacao:{
    label:'Retificação',
    descricao:'Editar pessoas já gravadas, corrigir dados existentes e excluir documentos quando permitido. Funciona independentemente da permissão Cadastro.'
  },
  retificacao_propria:{
    label:'Retificação dos próprios cadastros',
    descricao:'Editar e corrigir somente pessoas que foram cadastradas pelo próprio usuário. Não autoriza alterações em cadastros criados por outras pessoas.'
  },
  conferencia:{
    label:'Conferência',
    descricao:'Conferir documentos e registrar validações no cadastro da pessoa.'
  },
  minuta:{
    label:'Minutas jurídicas',
    descricao:'Acessar o módulo de minutas, gerar novas versões e registrar revisão jurídica.'
  },
  distribuicao:{
    label:'Distribuir processos',
    descricao:'Receber tarefas individuais de distribuição, acessar os documentos da pessoa e concluir a tarefa informando o número do processo no TRF4.'
  },
  gestao_distribuicao:{
    label:'Gerenciar distribuição',
    descricao:'Atribuir e reatribuir tarefas de distribuição entre usuários autorizados e acompanhar a fila de trabalho.'
  },
  administracao:{
    label:'Administração',
    descricao:'Gerenciar usuários, perfis, APIs, configurações e o modelo oficial da petição.'
  }
});

const ROLE_DESCRIPTIONS=Object.freeze({
  CONSULTA:'Acesso somente para consulta das informações já registradas.',
  NOVO_USUARIO:'Perfil legado de primeiro acesso com Consulta e Cadastro.',
  PROFESSOR_RESIDENTE:'Professor ou Residente. Recebe automaticamente as permissões operacionais do perfil, exceto Administração e Distribuir processos.',
  COLABORADOR:'Consulta, Cadastro e Retificação limitada aos cadastros criados pelo próprio colaborador.',
  ALUNO:'Consulta e Distribuir processos, para receber e concluir tarefas de distribuição atribuídas ao aluno.',
  CADASTRO:'Consulta e inclusão de pessoas e documentos.',
  CONFERENCIA:'Cadastro, retificação e conferência documental.',
  JURIDICO:'Conferência e atividades jurídicas, incluindo minutas e execução de tarefas de distribuição.',
  ADMIN:'Acesso integral ao sistema, gestão da distribuição e configurações administrativas.'
});

function props_(){
  return PropertiesService.getScriptProperties();
}

function fail_(message){
  throw new Error(message);
}

function required_(v,label){
  if(v===undefined||v===null||String(v).trim()==='')fail_('Informe '+label+'.');
  return v;
}

function uid_(){
  return Utilities.getUuid();
}

function hash_(value){
  return Utilities.computeDigest(
    Utilities.DigestAlgorithm.SHA_256,
    typeof value==='string'?value:JSON.stringify(value)
  ).map(x=>('0'+((x+256)%256).toString(16)).slice(-2)).join('');
}

function id_(prefix,key){
  return prefix+'_'+hash_(key).slice(0,28);
}

function now_(){
  return new Date().toISOString();
}

function bool_(v){
  return v===true||v==='true';
}

function clone_(v){
  return JSON.parse(JSON.stringify(v));
}

function cfg_(){
  const c=clone_(DEFAULTS);

  all_('Configuracoes').forEach(r=>{
    c[r.chave]=JSON.parse(r.valor);
  });

  if(
    JSON.stringify(c.entidades)===
    JSON.stringify(Array.from(LEGACY_ENTIDADES_PADRAO))
  ){
    c.entidades=Array.from(ENTIDADES_PADRAO);
  }

  c.municipios=municipiosComJurisdicao_(c.municipios);
  return c;
}

/** Regra única para cadastro, planilha e minuta. */
function normalizarMunicipio_(texto){
  return String(texto||'').trim().toUpperCase().normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'').replace(/[–—]/g,'-')
    .replace(/\s*-\s*/g,'-').replace(/\s+/g,' ');
}

function determinarJurisdicao(municipio){
  const nome=normalizarMunicipio_(municipio);
  for(const jurisdicao of Object.keys(JURISDICOES)){
    if(JURISDICOES[jurisdicao].some(m=>normalizarMunicipio_(m)===nome)){
      return jurisdicao;
    }
  }
  return '';
}

function municipiosComJurisdicao_(existentes){
  const porNome={};
  (Array.isArray(existentes)?existentes:[]).forEach(m=>{
    if(typeof m==='string'&&m.trim())porNome[normalizarMunicipio_(m)]=m.trim();
  });
  // Os nomes padronizados prevalecem; municípios adicionais são preservados.
  DEFAULTS.municipios.forEach(m=>porNome[normalizarMunicipio_(m)]=m);
  return Object.values(porNome).sort((a,b)=>a.localeCompare(b,'pt-BR'));
}

function jurisdicaoPessoa_(p){
  if(p.uf&&String(p.uf).trim().toUpperCase()!=='RS')return '';
  return determinarJurisdicao(p.cidade);
}

/** Atualização idempotente de instalações existentes, com auditoria de registros. */
function atualizarJurisdicoes_(){
  ensureEntitySchema_('Pessoas');
  const ctx={email:identity_(),op:'jurisdicoes_'+uid_(),hash:'jurisdicoes-v1',changes:[]};
  const config=all_('Configuracoes').find(r=>r.chave==='municipios');
  if(config){
    const lista=municipiosComJurisdicao_(JSON.parse(config.valor));
    if(JSON.stringify(lista)!==config.valor){
      change_(ctx,'Configuracoes',config.id,{chave:'municipios',valor:JSON.stringify(lista)},config.versao);
    }
  }
  const alterados=new Set();
  all_('Pessoas').forEach(p=>{
    const jurisdicao=jurisdicaoPessoa_(p);
    if(p.jurisdicao!==jurisdicao){
      change_(ctx,'Pessoas',p.id,Object.assign({},p,{jurisdicao}),p.versao);
      alterados.add(p.id);
    }
  });
  if(alterados.size){
    all_('Atendimentos').filter(a=>alterados.has(a.pessoaId)).forEach(a=>touch_(ctx,a));
  }
  if(ctx.changes.length)commit_(ctx,{mensagem:'Municípios e jurisdições atualizados.'});
}

let DATA_CACHE = {};

function resetData_(){
  DATA_CACHE={};
}

function ss_(){
  const id=props_().getProperty('SPREADSHEET_ID');

  if(!id){
    fail_(
      'Execute instalar pelo editor do Apps Script.'
    );
  }

  try{
    return SpreadsheetApp.openById(
      id
    );

  }catch(e){
    fail_('O servidor não conseguiu acessar o banco do Povo das Águas. Verifique SPREADSHEET_ID e as permissões do proprietário.');
  }
}

function headers_(entity){
  if(!SCHEMA[entity])fail_('Entidade inválida.');
  return COMMON.concat(SCHEMA[entity]);
}

/**
 * Mantém compatibilidade com bancos já instalados.
 * Só é permitida migração aditiva no final do cabeçalho.
 * Nenhuma coluna existente é apagada, movida ou renomeada.
 */
function ensureEntitySchema_(entity){
  if(!SCHEMA[entity])fail_('Entidade inválida.');

  const sh=ss_().getSheetByName(entity);
  if(!sh)fail_('Aba não encontrada: '+entity+'.');

  const expected=headers_(entity);
  const lastColumn=sh.getLastColumn();

  if(lastColumn===0){
    sh.getRange(1,1,1,expected.length).setValues([expected]);
    sh.setFrozenRows(1);
    sh.getRange(1,1,1,expected.length).setBackground('#12364a').setFontColor('#ffffff');
    sh.getRange(1,1,sh.getMaxRows(),expected.length).setNumberFormat('@');
    return sh;
  }

  const current=sh.getRange(1,1,1,lastColumn).getDisplayValues()[0];

  if(JSON.stringify(current)===JSON.stringify(expected)){
    return sh;
  }

  const prefixIsCompatible=
    current.length<expected.length&&
    current.every((value,index)=>value===expected[index]);

  if(!prefixIsCompatible){
    fail_('Cabeçalhos alterados: '+entity+'. A migração automática só acrescenta novas colunas ao final.');
  }

  const missing=expected.slice(current.length);
  sh.getRange(1,current.length+1,1,missing.length).setValues([missing]);
  sh.getRange(1,current.length+1,sh.getMaxRows(),missing.length).setNumberFormat('@');
  SpreadsheetApp.flush();
  resetData_();
  return sh;
}

function all_(entity){
  if(DATA_CACHE[entity])return DATA_CACHE[entity];

  const sh=ensureEntitySchema_(entity);
  const rows=sh.getDataRange().getDisplayValues();
  const heads=headers_(entity);

  if(JSON.stringify(rows[0])!==JSON.stringify(heads))fail_('Cabeçalhos alterados: '+entity);

  return DATA_CACHE[entity]=rows
    .slice(1)
    .filter(r=>r[0])
    .map(r=>Object.fromEntries(heads.map((h,i)=>[h,h==='versao'?Number(r[i]):r[i]])));
}

function get_(entity,id){
  return all_(entity).find(r=>r.id===id)||fail_('Registro não encontrado: '+entity);
}

function row_(entity,id){
  const sh=ensureEntitySchema_(entity);
  const values=sh.getRange(1,1,Math.max(sh.getLastRow(),1),1).getDisplayValues();
  const i=values.findIndex(r=>r[0]===id);
  return i<0?null:i;
}

function record_(entity,id,data,before,user){
  const r={
    id,
    versao:before?before.versao+1:1,
    criadoEm:before?before.criadoEm:now_(),
    alteradoEm:now_(),
    usuario:user
  };

  SCHEMA[entity].forEach(k=>r[k]=data[k]===undefined?'':data[k]);
  return r;
}

function change_(ctx,entity,id,data,version){
  const before=all_(entity).find(r=>r.id===id);

  if(before&&Number(version)!==before.versao){
    fail_('CONFLITO: o registro mudou. Reabra a ficha antes de salvar.');
  }

  const after=record_(entity,id,data,before,ctx.email);
  ctx.changes.push({entity,before:before||null,after});
  return after;
}

function remove_(ctx,entity,id,version){
  const before=
    all_(entity)
      .find(r=>r.id===id);

  if(!before){
    fail_(
      'Registro não encontrado: '+
      entity
    );
  }

  if(
    Number(version)!==
    before.versao
  ){
    fail_(
      'CONFLITO: o registro mudou. Reabra a ficha antes de excluir.'
    );
  }

  ctx.changes.push({
    entity,
    before,
    after:null
  });

  return before;
}


/** Atualização, exclusão, auditoria e recibo idempotente em uma única transação Sheets. */
function commit_(ctx,result){
  const changes=
    ctx.changes.slice();

  ctx.changes.forEach(c=>{
    const target=
      c.after||
      c.before;

    changes.push({
      entity:'Historico',
      after:record_(
        'Historico',
        uid_(),
        {
          entidade:c.entity,
          registroId:
            target.id,
          antes:
            JSON.stringify(
              authAuditRecord_(c.entity,c.before)
            ),
          depois:
            JSON.stringify(
              authAuditRecord_(c.entity,c.after)
            ),
          operacao:ctx.op
        },
        null,
        ctx.email
      )
    });
  });

  changes.push({
    entity:'Operacoes',
    after:record_(
      'Operacoes',
      ctx.op,
      {
        hash:ctx.hash,
        resultado:JSON.stringify(
          result
        )
      },
      null,
      ctx.email
    )
  });

  const deletes=
    changes
      .filter(c=>
        c.before&&
        c.after===null
      )
      .map(c=>{
        const sh=
          ensureEntitySchema_(
            c.entity
          );

        const index=
          row_(
            c.entity,
            c.before.id
          );

        if(index===null){
          fail_(
            'Registro a excluir não localizado: '+
            c.entity
          );
        }

        return {
          entity:c.entity,
          sheetId:sh.getSheetId(),
          index
        };
      })
      .sort((a,b)=>{
        if(a.sheetId!==b.sheetId){
          return a.sheetId-b.sheetId;
        }

        return b.index-a.index;
      });

  const next={};
  const requests=[];

  deletes.forEach(item=>{
    requests.push({
      deleteDimension:{
        range:{
          sheetId:item.sheetId,
          dimension:'ROWS',
          startIndex:item.index,
          endIndex:item.index+1
        }
      }
    });
  });

  changes
    .filter(c=>
      c.after!==null
    )
    .forEach(c=>{
      const sh=
        ensureEntitySchema_(
          c.entity
        );

      let index=
        row_(
          c.entity,
          c.after.id
        );

      if(index===null){
        if(
          next[c.entity]===
          undefined
        ){
          next[c.entity]=
            sh.getLastRow();
        }

        index=
          next[c.entity]++;
      }

      if(
        index>=
        sh.getMaxRows()
      ){
        requests.push({
          appendDimension:{
            sheetId:
              sh.getSheetId(),
            dimension:'ROWS',
            length:
              index-
              sh.getMaxRows()+
              1
          }
        });
      }

      const values=
        headers_(
          c.entity
        ).map(k=>({
          userEnteredValue:{
            stringValue:String(
              c.after[k]===
                undefined
                ?''
                :c.after[k]
            )
          }
        }));

      requests.push({
        updateCells:{
          range:{
            sheetId:
              sh.getSheetId(),
            startRowIndex:index,
            endRowIndex:index+1,
            startColumnIndex:0,
            endColumnIndex:
              values.length
          },
          rows:[
            {
              values
            }
          ],
          fields:
            'userEnteredValue'
        }
      });
    });

  Sheets.Spreadsheets.batchUpdate(
    {
      requests
    },
    ss_().getId()
  );

  SpreadsheetApp.flush();
  resetData_();

  return result;
}

function version_(row,expected){
  if(row.versao!==Number(expected))fail_('CONFLITO: registro alterado por outro usuário. Reabra a ficha.');
}

function touch_(ctx,a){
  return change_(
    ctx,
    'Atendimentos',
    a.id,
    Object.assign({},a,{
      revisao:Number(a.revisao||0)+1,
      conferencia:'',
      situacao:'EM_PREPARACAO'
    }),
    a.versao
  );
}

function snapshot_(a,p){
  return hash_({
    atendimento:a,
    pessoa:p,
    documentos:effectiveDocs_(a),
    pendencias:all_('Pendencias').filter(d=>d.atendimentoId===a.id)
  });
}

function identity_(){
  const email=String(
    PDA_AUTH_CONTEXT_EMAIL_||
    ''
  )
    .trim()
    .toLowerCase();

  if(!email){
    fail_(
      'AUTH: sessão autenticada necessária. Entre novamente com seu e-mail e senha.'
    );
  }

  return email;
}

function activeUser_(){
  const email=identity_();

  const user=all_('Usuarios')
    .find(r=>
      String(r.email||'').toLowerCase()===email&&
      bool_(r.ativo)
    );

  if(!user){
    fail_(
      'Seu usuário não está autorizado ou está com o acesso desativado.'
    );
  }

  return user;
}

function rolePermissions_(perfil){
  return Array.from(
    ROLES[perfil]||[]
  );
}

function parseUserPermissions_(user){
  const raw=String(
    user&&user.permissoes||''
  ).trim();

  if(!raw){
    return rolePermissions_(
      user&&user.perfil
    );
  }

  try{
    const parsed=JSON.parse(raw);

    if(!Array.isArray(parsed)){
      return rolePermissions_(
        user&&user.perfil
      );
    }

    const cleaned=
      parsed
        .map(v=>String(v||'').trim())
        .filter(v=>
          Object.prototype.hasOwnProperty.call(
            PERMISSIONS,
            v
          )
        );

    /*
     * Migração das permissões introduzidas com o fluxo de distribuição.
     * Usuários gravados antes da versão 2 recebem, uma única vez logicamente,
     * as novas permissões padrão do seu perfil. Depois que forem salvos pela
     * Administração, permissoesVersao=2 faz prevalecer exatamente as caixas
     * marcadas pelo administrador.
     */
    if(
      Number(
        user&&user.permissoesVersao||
        0
      )<2
    ){
      rolePermissions_(
        user&&user.perfil
      ).forEach(permission=>{
        if(!cleaned.includes(permission)){
          cleaned.push(permission);
        }
      });
    }

    return [
      ...new Set(
        cleaned
      )
    ];

  }catch(e){
    return rolePermissions_(
      user&&user.perfil
    );
  }
}

function effectivePermissions_(user){
  const permissions=
    parseUserPermissions_(user);

  /*
   * Consulta é a permissão estrutural mínima para um usuário ativo.
   */
  if(!permissions.includes('consulta')){
    permissions.unshift('consulta');
  }

  return permissions;
}

function hasPermission_(user,permission){
  return effectivePermissions_(user)
    .includes(permission);
}

function authorize_(permission){
  const user=activeUser_();

  if(
    !hasPermission_(
      user,
      permission
    )
  ){
    fail_(
      'Acesso não autorizado para '+
      permission+
      '.'
    );
  }

  return user.email;
}

function personCreatorEmail_(p){
  const explicit=String(p&&p.criadoPor||'').trim().toLowerCase();
  if(explicit)return explicit;

  if(Number(p&&p.versao||0)===1&&p&&p.usuario){
    return String(p.usuario).trim().toLowerCase();
  }

  const history=all_('Historico')
    .filter(h=>h.entidade==='Pessoas'&&h.registroId===p.id)
    .sort((a,b)=>String(a.criadoEm||'').localeCompare(String(b.criadoEm||'')));

  for(const item of history){
    try{
      const before=JSON.parse(item.antes||'null');
      const after=JSON.parse(item.depois||'null');

      if(!before&&after){
        const creator=String(after.criadoPor||after.usuario||'').trim().toLowerCase();
        if(creator)return creator;
      }
    }catch(e){}
  }

  return '';
}

function canRetifyPerson_(user,p){
  if(hasPermission_(user,'retificacao')){
    return true;
  }

  if(!hasPermission_(user,'retificacao_propria')){
    return false;
  }

  const creator=personCreatorEmail_(p);

  return !!creator&&authUserEmailMatches_(user,creator);
}

function authorizePersonRetification_(p){
  const user=activeUser_();

  if(!canRetifyPerson_(user,p)){
    fail_('Você somente pode retificar cadastros que tenha autorização para editar.');
  }

  return user.email;
}

function canWritePersonContent_(user,p){
  if(
    hasPermission_(
      user,
      'retificacao'
    )
  ){
    return true;
  }

  const creator=
    personCreatorEmail_(
      p
    );

  const own=
    !!creator&&
    authUserEmailMatches_(user,creator);

  if(!own){
    return false;
  }

  return (
    hasPermission_(
      user,
      'cadastro'
    )||
    hasPermission_(
      user,
      'retificacao_propria'
    )
  );
}

function authorizePersonContentWrite_(p){
  const user=
    activeUser_();

  if(
    !canWritePersonContent_(
      user,
      p
    )
  ){
    fail_(
      'Você não pode alterar documentos ou gerar peças para um cadastro criado por outro usuário.'
    );
  }

  return user.email;
}

function googleResourceAccessLevel_(user){
  if(
    !user||
    !bool_(
      user.ativo
    )
  ){
    return 'NONE';
  }

  /*
   * Na arquitetura de implantação única, toda gravação é executada pelo
   * proprietário do Web App e passa pelas permissões do sistema. Usuários
   * ativos recebem somente leitura direta no Drive para abrir/baixar os
   * documentos; nunca edição direta da pasta raiz ou do banco.
   */
  return 'VIEWER';
}

function removeGoogleAccess_(resource,email){
  try{
    resource.removeEditor(email);
  }catch(e){}

  try{
    resource.removeViewer(email);
  }catch(e){}
}

function setGoogleAccess_(resource,email,level){
  if(level==='EDITOR'){
    try{
      resource.addEditor(email);
      return;
    }catch(e){
      fail_(
        'Não foi possível conceder acesso de edição no Google Drive para '+
        email+
        ': '+
        (e.message||String(e))
      );
    }
  }

  if(level==='VIEWER'){
    try{
      try{
        resource.removeEditor(email);
      }catch(e){}

      resource.addViewer(email);
      return;
    }catch(e){
      fail_(
        'Não foi possível conceder acesso de consulta no Google Drive para '+
        email+
        ': '+
        (e.message||String(e))
      );
    }
  }

  removeGoogleAccess_(
    resource,
    email
  );
}

/**
 * O Web App executa como o proprietário e a identidade do usuário é validada
 * pela sessão do aplicativo. Esta sincronização permanece apenas para permitir
 * a abertura direta de arquivos do Google Drive pela interface:
 *
 * - usuário ativo -> leitor dos arquivos diretos;
 * - qualquer gravação -> executada pelo servidor como proprietário;
 * - usuário inativo -> acesso direto removido.
 */
function syncGoogleResourcesForUser_(user,ctx){
  const email=String(
    user&&user.email||''
  )
    .trim()
    .toLowerCase();

  required_(
    email,
    'e-mail Google do usuário'
  );

  const owner=String(
    props_().getProperty(
      'OWNER_EMAIL'
    )||''
  )
    .trim()
    .toLowerCase();

  if(email===owner){
    return {
      email,
      nivel:'PROPRIETARIO'
    };
  }

  const level=
    googleResourceAccessLevel_(
      user
    );

  // Compartilhamento explícito somente dos documentos, nunca da raiz ou do banco.
  const fileIds=new Set();
  all_('Documentos').forEach(r=>{if(r.fileId)fileIds.add(r.fileId);});
  all_('Minutas').forEach(r=>{if(r.fileId)fileIds.add(r.fileId);if(r.pdfFileId)fileIds.add(r.pdfFileId);});
  const resources=Array.from(fileIds).map(id=>({nome:'documento '+id,item:DriveApp.getFileById(id)}));

  resources.forEach(resource=>{
    setGoogleAccess_(
      resource.item,
      email,
      level
    );

    if(
      ctx&&
      Array.isArray(ctx.effects)
    ){
      ctx.effects.push(
        (
          level==='NONE'
            ?'Acesso Google removido'
            :'Acesso Google '+level+' concedido'
        )+
        ': '+
        resource.nome+
        ' — '+
        email
      );
    }
  });

  return {
    email,
    nivel:level
  };
}

function syncAllGoogleResources_(ctx){
  const results=[];

  all_('Usuarios')
    .forEach(user=>{
      results.push(
        syncGoogleResourcesForUser_(
          user,
          ctx
        )
      );
    });

  return {
    quantidade:results.length,
    usuarios:results,
    mensagem:
      'Acessos Google sincronizados para '+
      results.length+
      ' usuário(s).'
  };
}

