function distributionQueue_(){
  const people=
    all_('Pessoas');

  const users=
    all_('Usuarios');

  const peopleById=
    new Map(
      people.map(p=>[
        p.id,
        p
      ])
    );

  const usersByEmail=
    new Map(
      users.map(u=>[
        String(
          u.email||
          ''
        ).toLowerCase(),
        u
      ])
    );

  const tasks=
    all_('Tarefas')
      .filter(t=>
        t.tipo===
        DISTRIBUTION_TASK_TYPE
      )
      .sort((a,b)=>{
        const aDone=
          a.situacao===
          DISTRIBUTION_TASK_DONE;

        const bDone=
          b.situacao===
          DISTRIBUTION_TASK_DONE;

        if(aDone!==bDone){
          return aDone
            ?1
            :-1;
        }

        return String(
          b.alteradoEm||
          b.criadoEm||
          ''
        ).localeCompare(
          String(
            a.alteradoEm||
            a.criadoEm||
            ''
          )
        );
      })
      .map(t=>
        distributionTaskSummary_(
          t,
          peopleById,
          usersByEmail
        )
      );

  return {
    tarefas:tasks,
    usuarios:
      distributionUsers_(),
    indicadores:{
      semResponsavel:
        tasks.filter(t=>
          t.situacao===
          DISTRIBUTION_TASK_PENDING
        ).length,
      atribuidas:
        tasks.filter(t=>
          t.situacao===
          DISTRIBUTION_TASK_ASSIGNED
        ).length,
      concluidas:
        tasks.filter(t=>
          t.situacao===
          DISTRIBUTION_TASK_DONE
        ).length
    }
  };
}

