      jurisdicao:task.jurisdicao,
      valorCausa:task.valorCausa,
      atribuidaEm:now_(),
      concluidaEm:'',
      processoId:'',
      observacoes:
        task.observacoes||
        ''
    },
    task.versao
  );
}

function normalizeTrf4ProcessNumber_(value){
  const digits=
    String(
      value||
      ''
    ).replace(
      /\D/g,
      ''
    );

  if(
    digits.length!==20
  ){
    fail_(
      'Informe o número completo do processo no padrão CNJ, por exemplo 5001234-56.2026.4.04.7100.'
    );
  }

  if(
    digits.slice(
      13,
      14
    )!=='4'||
    digits.slice(
      14,
      16
    )!=='04'
  ){
    fail_(
      'O número informado não corresponde ao padrão da Justiça Federal da 4ª Região (4.04).'
    );
  }

  return (
    digits.slice(0,7)+
    '-'+
    digits.slice(7,9)+
    '.'+
    digits.slice(9,13)+
    '.'+
    digits.slice(13,14)+
    '.'+
    digits.slice(14,16)+
    '.'+
    digits.slice(16,20)
  );
}

function completeDistributionTask_(ctx,q){
  required_(
    q.id,
    'tarefa'
  );

  required_(
    q.numeroProcesso,
    'número do processo'
  );

  const task=
    get_(
      'Tarefas',
      q.id
    );

  if(
    task.tipo!==
    DISTRIBUTION_TASK_TYPE
  ){
    fail_(
      'Tarefa de distribuição inválida.'
    );
  }

  if(
    task.situacao===
    DISTRIBUTION_TASK_DONE
  ){
    fail_(
      'Esta tarefa já foi concluída.'
    );
  }

  if(
    String(
      task.responsavel||
      ''
    ).toLowerCase()!==
    String(
      ctx.email||
      ''
    ).toLowerCase()
  ){
    fail_(
      'Somente o usuário responsável pela tarefa pode concluí-la.'
    );
  }

  const numero=
    normalizeTrf4ProcessNumber_(
      q.numeroProcesso
    );

  const duplicate=
    all_('Processos')
      .find(p=>
        String(
          p.numero||
          ''
        )===numero
      );

  if(duplicate){
    fail_(
      'Esse número de processo já está cadastrado no sistema.'
    );
  }

  const p=
    get_(
      'Pessoas',
      task.pessoaId
    );

  const processId=
    id_(
      'PROC',
      p.id+':'+numero
    );

  const process=
    change_(
      ctx,
      'Processos',
      processId,
      {
        pessoaId:p.id,
        atendimentoId:'',
        numero,
        juizo:
          task.jurisdicao||
          p.jurisdicao||
          jurisdicaoPessoa_(p)||
          '',
        distribuidoEm:now_(),
        responsavel:ctx.email,
        movimentacoes:JSON.stringify([])
      }
    );

  const updatedTask=
    change_(
      ctx,
      'Tarefas',
      task.id,
      {
        tipo:task.tipo,
        pessoaId:task.pessoaId,
        responsavel:task.responsavel,
        situacao:DISTRIBUTION_TASK_DONE,
        jurisdicao:
          task.jurisdicao||
          p.jurisdicao||
          '',
        valorCausa:
          task.valorCausa||
          String(
            valorCausaDefeso_(
              p.parcelasNaoRecebidas
            )
          ),
        atribuidaEm:task.atribuidaEm,
        concluidaEm:now_(),
        processoId:process.id,
        observacoes:
          'Distribuição concluída. Processo TRF4: '+
          numero
      },
      task.versao
    );

  return {
    tarefa:updatedTask,
    processo:process,
    mensagem:
      'Distribuição concluída. Processo '+
      numero+
      ' vinculado a '+
      p.nome+
      '.'
  };
}

function reconcileDistributionTasks_(ctx){
  const people=
    all_('Pessoas');

  const docs=
    all_('Documentos');

  const processes=
    all_('Processos');

  let created=0;

  people.forEach(p=>{
    const hasInitial=
      docs.some(d=>
        d.atendimentoId===
          personOwnerKey_(p.id)&&
        d.categoria===
          'INICIAL_SEGURO_DEFESO_2025'&&
        bool_(d.vigente)
      );

    const hasProcess=
      processes.some(process=>
        process.pessoaId===
          p.id&&
        String(
          process.numero||
          ''
        ).trim()
      );

    if(
      hasInitial&&
      !hasProcess&&
      !distributionTaskForPerson_(
        p.id
      )
    ){
      ensureDistributionTask_(
        ctx,
        p
      );

      created++;
    }
  });

  return {
    criadas:created,
    mensagem:
      created+
      (
        created===1
          ?' tarefa de distribuição criada.'
          :' tarefas de distribuição criadas.'
      )
  };
}

const PERSON_TEMPLATE_PLACEHOLDERS=[
  'NOME_COMPLETO',
  'CPF',
  'ENDERECO',
  'CIDADE_UF',
  'TELEFONE',
  'PARCELAS_NAO_RECEBIDAS',
  'VALOR_CAUSA'
];

const OPTIONAL_TEMPLATE_PLACEHOLDERS=['JURISDICAO'];
const INITIAL_PETITION_DOCUMENT_CATEGORY='INICIAL_SEGURO_DEFESO_2025';

const TEMPLATE_PLACEHOLDER_ALIASES={
  'JURISDIÇÃO':'JURISDICAO',
  'NOME COMPLETO':'NOME_COMPLETO',
  'ENDEREÇO':'ENDERECO',
  'ENDERECO':'ENDERECO',
  'CIDADE':'CIDADE_UF',
  'PARCELAS QUE NÃO RECEBEU':'PARCELAS_NAO_RECEBIDAS',
  'PARCELAS QUE NAO RECEBEU':'PARCELAS_NAO_RECEBIDAS',
  '##VALOR':'VALOR_CAUSA'
};

function docParts_(doc){
  const parts=[];

  if(typeof doc.getTabs==='function'&&DocumentApp.TabType){
    function visit(tab){
      if(tab.getType()===DocumentApp.TabType.DOCUMENT_TAB){
        const d=tab.asDocumentTab();
        parts.push(d.getBody());
        if(d.getHeader())parts.push(d.getHeader());
        if(d.getFooter())parts.push(d.getFooter());
      }

      tab.getChildTabs().forEach(visit);
    }

    doc.getTabs().forEach(visit);
  }else{
    parts.push(doc.getBody());
    if(doc.getHeader())parts.push(doc.getHeader());
    if(doc.getFooter())parts.push(doc.getFooter());
  }

  return parts;
}

function tokens_(parts){
  return parts.flatMap(p=>p.getText().match(/<<[^<>]+>>/g)||[]);
}

function regexEscape_(value){
  const special=['\\','^','$','.','|','?','*','+','(',')','[',']','{','}'];

  return String(value)
    .split('')
    .map(ch=>special.includes(ch)?'\\\\'+ch:ch)
    .join('');
}

function openDocument_(id){
  let lastError=null;

  for(let i=0;i<6;i++){
    try{
      return DocumentApp.openById(id);
    }catch(e){
      lastError=e;
      Utilities.sleep(300);
    }
  }

  throw lastError||new Error('Não foi possível abrir o Google Docs.');
}

function replaceToken_(parts,key,value){
  const token='<<'+key+'>>';
  const pattern=regexEscape_(token);
  const replacement=String(value===undefined||value===null?'':value);

  parts.forEach(part=>{
    let found=part.findText(pattern);

    while(found){
      const text=found.getElement().asText();
      const start=found.getStartOffset();
      const end=found.getEndOffsetInclusive();
      const attrs=text.getAttributes(start);

      text.deleteText(start,end);
      text.insertText(start,replacement);

      if(replacement.length){
        text.setAttributes(start,start+replacement.length-1,attrs);
      }

      found=part.findText(pattern);
    }
  });
}

function normalizeTemplatePlaceholders_(doc){
  const parts=docParts_(doc);

  Object.keys(TEMPLATE_PLACEHOLDER_ALIASES).forEach(alias=>{
    const canonical=TEMPLATE_PLACEHOLDER_ALIASES[alias];
    const from='<<'+alias+'>>';
    const to='<<'+canonical+'>>';

    if(from===to)return;

    parts.forEach(part=>{
      part.replaceText(regexEscape_(from),to);
    });
  });

  return parts;
}

function validatePersonTemplate_(id){
  required_(id,'modelo Google Docs');

  const file=DriveApp.getFileById(id);

  if(file.getMimeType()!==MimeType.GOOGLE_DOCS){
    fail_('Modelo deve ser Google Docs.');
  }

  const doc=openDocument_(id);
  const parts=normalizeTemplatePlaceholders_(doc);
  const found=tokens_(parts);

  const missing=PERSON_TEMPLATE_PLACEHOLDERS.filter(
    key=>!found.includes('<<'+key+'>>')
  );

  const unknown=[...new Set(found.filter(
    token=>!PERSON_TEMPLATE_PLACEHOLDERS.concat(OPTIONAL_TEMPLATE_PLACEHOLDERS).includes(token.slice(2,-2))
  ))];

  if(missing.length||unknown.length){
    doc.saveAndClose();

    fail_(
      'Modelo incompatível. Ausentes: '+(missing.join(', ')||'nenhum')+
      '; desconhecidos: '+(unknown.join(', ')||'nenhum')+'.'
    );
  }

  doc.saveAndClose();
  return true;
}

function templatesFolder_(){
  const root=DriveApp.getFolderById(PDA.parent);
  const iterator=root.getFoldersByName('MODELOS');
  const folder=iterator.hasNext()?iterator.next():root.createFolder('MODELOS');

  if(iterator.hasNext()){
    fail_('Há mais de uma pasta MODELOS na raiz do Povo das Águas.');
  }

  return folder;
}

function activeTemplate_(){
  const configured=String(cfg_().templateId||'').trim();

  if(configured){
    try{
      const file=DriveApp.getFileById(configured);

      if(
        !file.isTrashed()&&
        file.getMimeType()===MimeType.GOOGLE_DOCS
      ){
        return file;
      }
    }catch(e){}
  }

  const folder=templatesFolder_();
  const iterator=folder.getFilesByName(SEGURO_DEFESO_2025.modeloNome);
  const found=[];

  while(iterator.hasNext()){
    const file=iterator.next();

    if(
      !file.isTrashed()&&
      file.getMimeType()===MimeType.GOOGLE_DOCS
    ){
      found.push(file);
    }
  }

  if(found.length>1){
    fail_(
      'Há mais de um modelo ativo chamado "'+
      SEGURO_DEFESO_2025.modeloNome+
      '" na pasta MODELOS.'
    );
  }

  if(!found.length){
    fail_(
      'Nenhum modelo de minuta está ativo. Envie o arquivo DOCX em Administração > Modelo de minuta.'
    );
  }

  return found[0];
}

function templateStatus_(){
  try{
    const file=activeTemplate_();

    return {
      configurado:true,
      id:file.getId(),
      nome:file.getName(),
      url:file.getUrl(),
      alteradoEm:file.getLastUpdated().toISOString()
    };

  }catch(e){
    return {
      configurado:false,
      id:'',
      nome:'',
      url:'',
      alteradoEm:'',
      mensagem:e.message||String(e)
    };
  }
}

function parcelasText_(value){
  const n=parcelasDefeso_(value);

  return {
    1:'1 (uma) parcela',
    2:'2 (duas) parcelas',
    3:'3 (três) parcelas',
    4:'4 (quatro) parcelas'
  }[n];
}

function valorCausaTexto_(value){
  const qtd=parcelasDefeso_(value);
  const total=valorCausaDefeso_(qtd);
  const parcela=SEGURO_DEFESO_2025.salarioMinimo;
  const descricao=qtd===1?'1 parcela não paga':qtd+' parcelas não pagas';

  return (
    moneyBR_(total)+
    ' ('+
    descricao+
    ' × R$ '+
    moneyBR_(parcela)+
