        d.id,
        d
      ])
    );

  const iniciais=
    documentos.filter(d=>
      d.categoria===
      'INICIAL_SEGURO_DEFESO_2025'
    );

  const relatorios=
    documentos.filter(d=>
      d.categoria===
      'RELATORIO_SEGURO_DEFESO_2025'
    );

  const aConferir=
    documentos.filter(d=>
      !bool_(
        d.conferido
      )
    );

  const valorCausas=
    pessoas.reduce(
      (total,p)=>
        total+
        causeValueFromPerson_(p),
      0
    );

  const valorCausasTramitacao=
    processos.reduce(
      (total,processo)=>{
        const p=
          peopleById.get(
            processo.pessoaId
          );

        return (
          total+
          causeValueFromPerson_(p)
        );
      },
      0
    );

  const currentEmail=
    String(
      identity_()||
      ''
    ).toLowerCase();

  const minhasTarefas=
    all_('Tarefas')
      .filter(t=>
        t.tipo===
          DISTRIBUTION_TASK_TYPE&&
        t.situacao!==
          DISTRIBUTION_TASK_DONE&&
        String(
          t.responsavel||
          ''
        ).toLowerCase()===
          currentEmail
      ).length;

  const ultimosCadastros=
    pessoas
      .slice()
      .sort((a,b)=>
        String(
          b.criadoEm||''
        ).localeCompare(
          String(
            a.criadoEm||''
          )
        )
      )
      .slice(
        0,
        6
      )
      .map(p=>({
        id:p.id,
        nome:p.nome,
        cpf:p.cpf,
        cidade:p.cidade,
        jurisdicao:p.jurisdicao,
        criadoEm:p.criadoEm,
        documentos:
          documentos.filter(d=>
            d.atendimentoId===
            personOwnerKey_(p.id)
          ).length
      }));

  const atividades=
    historico
      .slice()
      .sort((a,b)=>
        String(
          b.alteradoEm||
          b.criadoEm||
          ''
        ).localeCompare(
          String(
            a.alteradoEm||
            a.criadoEm||
            ''
          )
        )
      )
      .slice(
        0,
        7
      )
      .map(h=>({
        id:h.id,
        entidade:h.entidade,
        registroId:h.registroId,
        data:
          h.alteradoEm||
          h.criadoEm||
          '',
        usuario:h.usuario||'',
        descricao:
          dashboardActivityLabel_(
            h,
            peopleById,
            docsById
          )
      }));

  const jurisdicoes=
    pessoas.reduce(
      (acc,p)=>{
        const key=
          String(
            p.jurisdicao||
            'NÃO DEFINIDA'
          );

        acc[key]=
          (acc[key]||0)+1;

        return acc;
      },
      {}
    );

  return {
    atualizadoEm:now_(),
    pessoas:pessoas.length,
    documentos:documentos.length,
    aConferir:aConferir.length,
    iniciais:iniciais.length,
    relatorios:relatorios.length,
    acoesTramitacao:processos.length,
    minhasTarefas,
    valorCausas,
    valorCausasTramitacao,
    jurisdicoes,
    ultimosCadastros,
    atividades
  };
}

function profilePhoto_(user){
  if(!user.fotoId)return '';
  try{
    const file=DriveApp.getFileById(user.fotoId),blob=file.getBlob();
    if(file.isTrashed()||!/^image\/(jpeg|png|webp)$/.test(blob.getContentType()))return '';
    return 'data:'+blob.getContentType()+';base64,'+Utilities.base64Encode(blob.getBytes());
  }catch(e){return '';}
}

function authProfile(token){
  return withAuthSession_(token,s=>({usuario:authPublicUser_(s.user),foto:profilePhoto_(s.user)}));
}

function profilePhotoFolder_(){
  const root=DriveApp.getFolderById(props_().getProperty('ROOT_FOLDER_ID'));
  const folders=root.getFoldersByName('Fotos de perfil');
  return folders.hasNext()?folders.next():root.createFolder('Fotos de perfil');
}

function profileCreatePhoto_(user,base64,mime){
  if(typeof base64!=='string'||base64.length>410000||!base64.length||
    !/^[A-Za-z0-9+/]+={0,2}$/.test(base64)||!/^image\/(jpeg|png|webp)$/.test(mime))
    fail_('Selecione uma imagem JPEG, PNG ou WebP de até 300 KB.');
  const bytes=Utilities.base64Decode(base64),b=bytes.map(x=>(x+256)%256);
  const png=[137,80,78,71,13,10,26,10].every((x,i)=>b[i]===x);
  const jpeg=b[0]===255&&b[1]===216&&b[2]===255;
  const webp=b[0]===82&&b[1]===73&&b[2]===70&&b[3]===70&&b[8]===87&&b[9]===69&&b[10]===66&&b[11]===80;
  if(bytes.length>300*1024||!(mime==='image/png'?png:mime==='image/jpeg'?jpeg:webp))
    fail_('O arquivo não é uma imagem válida ou excede 300 KB.');
  const extension={'image/png':'png','image/jpeg':'jpg','image/webp':'webp'}[mime];
  return profilePhotoFolder_().createFile(Utilities.newBlob(bytes,mime,user.id+'_'+uid_()+'.'+extension));
}

function profileMigrateEmailReferences_(ctx,oldEmail,newEmail){
  // Mantém tarefas atuais na mesma conta; autoria histórica é resolvida por aliases.
  ['Tarefas','Atendimentos','Distribuicao','Processos'].forEach(entity=>{
    all_(entity).filter(r=>String(r.responsavel||'').trim().toLowerCase()===oldEmail).forEach(r=>{
      change_(ctx,entity,r.id,Object.assign({},r,{responsavel:newEmail}),r.versao);
    });
  });
}

function authUpdateProfile(token,q){
  q=q||{};
  return withAuthSession_(token,s=>{
    const user=s.user;version_(user,q.versao);
    const nome=String(q.nome||'').trim().replace(/\s+/g,' ');
    const nomeUsuario=String(q.nomeUsuario||'').trim().replace(/\s+/g,' ');
    const email=authEmail_(q.email),emailChanged=email!==user.email;
    if(!nome||nome.length>140||!nomeUsuario||nomeUsuario.length>80)fail_('Informe o nome e o nome de usuário (até 140 e 80 caracteres).');
    if(emailChanged){
      authLimit_('profile-password',user.id,8,15);
      if(!authPasswordMatches_(user,authPassword_(q.senhaAtual)))fail_('Senha atual incorreta.');
      authCheckAvailableEmail_(email,user.id);
    }
    const ctx=authContext_(user.email);
    let created=null;
    const aliases=authAliases_(user);
    if(emailChanged&&!aliases.includes(user.email))aliases.push(user.email);
    let fotoId=user.fotoId||'';
    if(q.removerFoto===true)fotoId='';
    if(q.base64){created=profileCreatePhoto_(user,q.base64,String(q.mime||''));fotoId=created.getId();}
    try{
      const updated=change_(ctx,'Usuarios',user.id,Object.assign({},user,{
        nome,nomeUsuario,email,fotoId,emailsAnteriores:JSON.stringify(aliases),
        sessionVersion:Number(user.sessionVersion||0)+(emailChanged?1:0)
      }),user.versao);
      if(emailChanged)profileMigrateEmailReferences_(ctx,user.email,email);
      const session=emailChanged?authNewSession_(ctx,updated):null;
      authPersist_(ctx);
      // Só descarta a foto anterior depois de confirmar a alteração.
      if(user.fotoId&&user.fotoId!==fotoId){try{DriveApp.getFileById(user.fotoId).setTrashed(true);}catch(e){}}
      return Object.assign({ok:true,usuario:authPublicUser_(updated)},session||{});
    }catch(e){
      // Uma resposta perdida pode ocorrer após commit. Confira o banco antes de descartar.
      if(created){
        try{resetData_();if(get_('Usuarios',user.id).fotoId!==created.getId())created.setTrashed(true);}catch(ignore){}
      }
      throw e;
    }
  });
}

function authChangePassword(token,senhaAtual,novaSenha){
  authPassword_(novaSenha);authPassword_(senhaAtual);
  return withAuthSession_(token,s=>{
    const user=s.user;authLimit_('profile-password',user.id,8,15);
    if(!authPasswordMatches_(user,senhaAtual))fail_('Senha atual incorreta.');
    const ctx=authContext_(user.email);
    const updated=change_(ctx,'Usuarios',user.id,Object.assign({},user,authPasswordFields_(novaSenha),{
      sessionVersion:Number(user.sessionVersion||0)+1
    }),user.versao);
    const result=authNewSession_(ctx,updated);authPersist_(ctx);return result;
  });
}

function personRetify_(ctx,q){
  required_(
    q.id,
    'cadastro a retificar'
  );

  const person=
    get_(
      'Pessoas',
      q.id
    );

  authorizePersonRetification_(
    person
  );

  return personSave_(
    ctx,
    q
  );
}

function personSave_(ctx,q){
  const before=q.id?get_('Pessoas',q.id):null;

  if(before){
    authorizePersonRetification_(before);
  }

  const c=cfg_();
  const p=validatePerson_(q,c,c.rascunhos!=='PERMITIR');

  p.criadoPor=
    before
      ?(
        before.criadoPor||
        personCreatorEmail_(before)||
        before.usuario||
        ''
      )
      :ctx.email;

  const other=all_('Pessoas').find(r=>r.cpf===p.cpf&&r.id!==q.id);
  if(other)fail_('CPF já cadastrado. Abra a pessoa existente: '+other.id);

  const saved=change_(ctx,'Pessoas',q.id||id_('PES',ctx.op),p,q.versao);
  const folder=personFolder_(saved);

  ctx.effects.push('Pasta da pessoa preservada no Drive: '+folder.getUrl());

  const distributionTask=
    distributionTaskForPerson_(
      saved.id
    );

  if(
    distributionTask&&
    distributionTask.situacao!==
      DISTRIBUTION_TASK_DONE
  ){
    change_(
      ctx,
      'Tarefas',
      distributionTask.id,
      {
        tipo:distributionTask.tipo,
        pessoaId:saved.id,
        responsavel:
          distributionTask.responsavel||
          '',
        situacao:distributionTask.situacao,
        jurisdicao:
          saved.jurisdicao||
          jurisdicaoPessoa_(saved)||
          '',
        valorCausa:String(
          valorCausaDefeso_(
            saved.parcelasNaoRecebidas
          )
        ),
        atribuidaEm:
          distributionTask.atribuidaEm||
          '',
        concluidaEm:'',
        processoId:'',
        observacoes:
          distributionTask.observacoes||
          ''
      },
      distributionTask.versao
    );
  }

  if(before){
    all_('Atendimentos')
      .filter(a=>a.pessoaId===before.id)
      .forEach(a=>touch_(ctx,a));
  }

  return Object.assign({},saved,{
    folderId:folder.getId(),
    folderUrl:folder.getUrl()
  });
}


function personRequiredDocumentErrors_(p){
  const owner=personOwnerKey_(p.id);
  const docs=all_('Documentos').filter(
    d=>d.atendimentoId===owner&&bool_(d.vigente)
  );
  const errors=[];

  cfg_().categorias.forEach(categoria=>{
    const categoryDocs=docs.filter(d=>d.categoria===categoria);
    const validFiles=categoryDocs.filter(d=>{
      try{
        const file=DriveApp.getFileById(d.fileId);
        return !file.isTrashed();
      }catch(e){
        return false;
      }
    });

    if(!validFiles.length){
      errors.push('Anexe '+documentLabel_(categoria)+'.');
      return;
    }

    if(categoria==='RESIDENCIA'){
      const residenceWithDate=validFiles.some(d=>{
        try{
          date_(d.vencimento);
          return true;
        }catch(e){
          return false;
        }
      });

      if(!residenceWithDate){
        errors.push('Informe uma data válida para o vencimento do comprovante de residência.');
      }

      const thirdPartyDocs=
        validFiles.filter(d=>
          bool_(d.terceiro)
        );

      if(thirdPartyDocs.length){
        const hasDeclaration=
          thirdPartyDocs.some(d=>
            bool_(d.declaracaoTerceiro)
          );

        if(!hasDeclaration){
          errors.push(
            'Confirme que há declaração de residência no comprovante em nome de terceiro.'
          );
        }

        const holderIdentityDocs=
          docs.filter(d=>
            d.categoria==='IDENTIDADE_TITULAR_RESIDENCIA'&&
            bool_(d.vigente)
          );

        const hasHolderIdentity=
          holderIdentityDocs.some(d=>{
            try{
              const file=DriveApp.getFileById(d.fileId);
              return !file.isTrashed();
            }catch(e){
              return false;
            }
          });

        if(!hasHolderIdentity){
          errors.push(
            'Anexe a carteira de identidade do titular da residência.'
          );
        }
      }
    }
  });

  return [...new Set(errors)];
}

/**
 * Chamado pelo formulário de Pessoas somente depois que o cadastro e todos os
 * uploads selecionados já foram confirmados em operações anteriores.
 */
function personFinalize_(ctx,q){
  required_(q.pessoaId,'pessoa');

  const p=get_('Pessoas',q.pessoaId);

  authorizePersonContentWrite_(
    p
  );

  parcelasDefeso_(p.parcelasNaoRecebidas);

  const documentErrors=personRequiredDocumentErrors_(p);

  if(documentErrors.length){
    fail_(
      'O cadastro não pode ser finalizado sem todos os documentos obrigatórios:\n'+
      documentErrors.join('\n')
    );
  }

  const folder=personFolder_(p);
  const minuta=generatePersonDraft_(ctx,p);
  const tarefaDistribuicao=
    ensureDistributionTask_(
      ctx,
      p
    );

  return {
    pessoaId:p.id,
    folderId:folder.getId(),
    folderUrl:folder.getUrl(),
    minutaBase:minuta,
    tarefaDistribuicao:
      tarefaDistribuicao
        ?tarefaDistribuicao.id
        :'',
    mensagem:
      'Cadastro, documentos e minuta concluídos. Tarefa de distribuição criada automaticamente.'
  };
}

/**
 * Gera ou atualiza a petição inicial diretamente a partir da Ficha e conferência.
 * Mantém as mesmas exigências documentais usadas na finalização do cadastro.
 */
function personInitialGenerate_(ctx,q){
  required_(q.pessoaId,'pessoa');

  const p=get_('Pessoas',q.pessoaId);

  authorizePersonContentWrite_(
    p
  );

  parcelasDefeso_(p.parcelasNaoRecebidas);

  const documentErrors=
    personRequiredDocumentErrors_(p);

  if(documentErrors.length){
    fail_(
      'A petição inicial não pode ser gerada enquanto houver documentos obrigatórios pendentes:\n'+
      documentErrors.join('\n')
    );
  }

  const folder=personFolder_(p);
  const minuta=generatePersonDraft_(ctx,p);
  const tarefaDistribuicao=
    ensureDistributionTask_(
      ctx,
      p
    );

  return {
    pessoaId:p.id,
    folderId:folder.getId(),
    folderUrl:folder.getUrl(),
    minutaBase:minuta,
    tarefaDistribuicao:
      tarefaDistribuicao
        ?tarefaDistribuicao.id
        :'',
    mensagem:
      'Petição inicial gerada e adicionada aos documentos da pessoa. A tarefa de distribuição foi garantida.'
  };
}


function personSearch_(q){
  const term=String(q.busca||'').trim().toLowerCase();

  return all_('Pessoas')
    .filter(p=>
      !term||
      p.nome.toLowerCase().includes(term)||
      p.cpf.includes(term.replace(/[.\- ]/g,''))||
      String(p.cidade||'').toLowerCase().includes(term)
    )
    .sort((a,b)=>
      String(a.nome||'').localeCompare(
        String(b.nome||''),
        'pt-BR',
        {sensitivity:'base'}
      )
    );
}

function processList_(){
  const people=
    new Map(
      all_('Pessoas').map(p=>[
        p.id,
        p
      ])
    );

  return all_('Processos')
    .slice()
    .sort((a,b)=>
      String(
        b.distribuidoEm||
        b.criadoEm||
        ''
      ).localeCompare(
        String(
          a.distribuidoEm||
          a.criadoEm||
          ''
        )
      )
    )
    .map(process=>{
      const p=
        people.get(
          process.pessoaId
        );

      return {
        id:process.id,
        numero:process.numero,
        pessoaId:process.pessoaId,
        pessoa:
          p
            ?p.nome
            :'Pessoa não localizada',
        cpf:
          p
            ?p.cpf
            :'',
        jurisdicao:
          process.juizo||
          (
            p
              ?p.jurisdicao
              :''
          ),
        distribuidoEm:process.distribuidoEm,
        responsavel:process.responsavel
      };
    });
}

